        operationNo: this.operationId
      }).then(function (res) {
        if (res.data.deviceOperationDetailVOList && res.data.deviceOperationDetailVOList.length > 0) {
          _this.deviceOperationDetailDTO = res.data.deviceOperationDetailVOList[0];
        }
      }).finally(function () {
        _this.detialLoading = false;
      });
    },
    validate: function validate(callback) {
      var _this2 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (callback) {
          //告警处置时间 赋值
          if (valid) {
            _this2.formValue.disposeTime = dateFormat(new Date());
            _this2.formValue.deviceOperationDetailDTO = _this2.deviceOperationDetailDTO;
            _this2.formValue.disposeResult = _this2.deviceOperationDetailDTO.disposeResult;
          }
          callback(valid);
        }
      });
    },
