        label: '设备分类',
        ciId: '1097745625841664'
      });
      this.ciIdList.push({
        name: 'deviceType',
        label: '设备类型',
        ciId: '1097745969774592',
        loading: false
      });
      this.ciIdList.push({
        name: 'isItal',
        label: '是否信创设备',
        ciId: '1104198218612736'
      });
      this.ciIdList.push({
        name: 'maker',
        label: '制造商',
        ciId: '1082610161090560'
      });
      this.ciIdList.push({
        name: 'brand',
        label: '品牌',
        ciId: '1082554947272704',
        loading: false
      });
      this.ciIdList.push({
        name: 'series',
        label: '系列',
        ciId: '1082609011851264',
        loading: false
      });
      this.ciIdList.push({
        name: 'deviceModel',
        label: '型号',
        ciId: '1082608047161344',
        loading: false
      });
      this.ciIdList.push({
