        name: 'procureTypeCode',
        label: '采购方式',
        ciId: '1083886445854720'
      });
      this.ciIdList.push({
        name: 'deviceStatus',
        label: '设备状态',
        ciId: '1103423111233536'
      });
      this.ciIdList.push({
        name: 'networkType',
        label: '所属网络',
        ciId: '1107942968721408'
      });

      //加载字典
      for (var i = 0; i < this.ciIdList.length; i++) {
        if (!this.ciIdList[i].loading) {
          this.getCmdbDictList(this.ciIdList[i]);
        }
      }
    },
    getCmdbDictList: function getCmdbDictList(item) {
      var _this3 = this;
      if (!item) {
        return;
      }
      //加载cmdb字典
      getDictCmdbList({
        ciId: item.ciId
      }).then(function (res) {
        if (item.name === 'deviceCategory') {
          // 设备分类
          _this3.deviceCategoryList = res.data;

          //设备分类默认为终端设备
          _this3.$set(_this3.deviceOperationDetailDTO, 'deviceCategory', _this3.deviceCategoryList.find(function (a) {
            return a.dictKey == _this3.$store.state.common.govern.device_terminal;
          }).dictKey);
        } else if (item.name === 'isItal') {
          // 是否是信创设备
          _this3.isItalList = res.data;
        } else if (item.name === 'deviceSource') {
          // 设备来源
          _this3.deviceSourceList = res.data;

          //设备来源默认非统一纳管：不可选
          _this3.$set(_this3.deviceOperationDetailDTO, 'deviceSource', _this3.deviceSourceList.find(function (a) {
